"""Seeded bugs of the payload `gpusnap2` (payloads/gpusnap2.c, payloads/gpusnap2-regs.h) that the host test must refuse, each for its own reason
(tools/test-q1n1-sp11-payload-gpusnap2.py runs them; docs/SP11-PAYLOAD-GPUSNAP2.md lists them). A mutant is an exact, once-only replacement in one of the two files, and names
the stage that must reject it and what that stage must say:

  harness       the native host test (tools/test-q1n1-sp11-payload-gpusnap2.c) built over the mutant exits non-zero, the suites in `suites` are among the ones that FAIL, and its
                diagnostics hold `reason` (the text of the failed check or of the model's violation)
  caps          the same, built with `defs` (small caps) and running only the cap suite
  audit         the IR audit (tools/sp11_payload_gpusnap2_audit.py) reports a problem that holds `reason`
  binary        the mutant links and the `gpusnap2` policy of tools/sp11_payload_testlib.py reports a violation that holds `reason`, or the link refuses it with a message that
                holds `reason`
  stack         the deepest chain of frames is deeper than the stack the ABI leaves

The audit and binary mutants are never run natively: some of them store to a device address. A defensive check that the shipped tables never trip (the window and range tests of
the read primitive, the dead-store guards) has no mutant of its own: removing it changes nothing a test can see, and the document says so.
Hardware: NOT RUN. Evidence: EXPERIMENTAL (host model and compiled code only)."""
from collections import namedtuple

Mutant = namedtuple('Mutant', 'name file old new stage suites reason defs')


def m(name, file, old, new, stage='harness', suites=(), reason='', defs=()):
    return Mutant(name, file, old, new, stage, tuple(suites), reason, tuple(defs))


H, C = 'payloads/gpusnap2-regs.h', 'payloads/gpusnap2.c'
NOLIST = 'a register no list names'
NOWIN = 'an address in no window the design names'
CDBWALK = "which the oracle's walk does not visit"
ORACLE = "the oracle's"


def row(key, old, new, reason=NOLIST, suites=('unit',)):
    """A register of the table moved to another word."""
    return m(f'{key.lower()}-register-moved', H, old, new, suites=suites, reason=reason)


